package com.mediflow.notification;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mediflow.notification.infrastructure.messaging.RegistrationNoticeDecoder;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.assertj.core.api.Assertions.*;

/** Reads the exact producer-generated bytes; it never formats or generates a replacement fixture. */
class RegistrationNoticeProducerContractTest {
    private final ObjectMapper mapper = new ObjectMapper().findAndRegisterModules();
    private final RegistrationNoticeDecoder decoder = new RegistrationNoticeDecoder(mapper);

    @ParameterizedTest
    @ValueSource(strings = {"awaiting_payment", "confirmed", "cancelled"})
    void acceptsOriginalClinicalSerializerBytes(String state) throws Exception {
        byte[] raw = fixture(state);
        var command = decoder.decode(raw);
        var payload = mapper.readTree(raw).path("payload");
        assertThat(command.registrationId().toString()).isEqualTo(payload.path("registrationId").textValue());
        assertThat(command.status()).isEqualTo(payload.path("status").textValue());
        assertThat(command.rawHash()).isEqualTo(java.util.HexFormat.of().formatHex(
                java.security.MessageDigest.getInstance("SHA-256").digest(raw)));
    }

    @Test void invalidBindingOrUnconfirmedQueueNumberOrWrongProducerAreRejected() throws Exception {
        var root = (ObjectNode) mapper.readTree(fixture("awaiting_payment"));
        ((ObjectNode) root.path("payload")).put("sourceId", java.util.UUID.randomUUID().toString());
        byte[] wrongBinding = mapper.writeValueAsBytes(root);
        assertThatThrownBy(() -> decoder.decode(wrongBinding)).isInstanceOf(IllegalArgumentException.class);
        root = (ObjectNode) mapper.readTree(fixture("awaiting_payment"));
        ((ObjectNode) root.path("payload")).put("queueNumber", 1);
        byte[] queued = mapper.writeValueAsBytes(root);
        assertThatThrownBy(() -> decoder.decode(queued)).isInstanceOf(IllegalArgumentException.class);
        root = (ObjectNode) mapper.readTree(fixture("awaiting_payment")); root.put("producer", "report-service");
        byte[] wrongProducer = mapper.writeValueAsBytes(root);
        assertThatThrownBy(() -> decoder.decode(wrongProducer)).isInstanceOf(IllegalArgumentException.class);
    }

    @Test void acceptsFollowUpSemanticsButRejectsSecondsAndOversizedQueue() throws Exception {
        // Derived semantic cases, distinct from the exact producer-byte acceptance above.
        var root = (ObjectNode) mapper.readTree(fixture("awaiting_payment"));
        ((ObjectNode) root.path("payload")).put("visitType", "FOLLOW_UP");
        assertThat(decoder.decode(mapper.writeValueAsBytes(root)).status()).isEqualTo("AWAITING_PAYMENT");
        ((ObjectNode) root.path("payload")).put("startTime", "09:00:00");
        byte[] seconds = mapper.writeValueAsBytes(root);
        assertThatThrownBy(() -> decoder.decode(seconds)).isInstanceOf(IllegalArgumentException.class);
        root = (ObjectNode) mapper.readTree(fixture("confirmed"));
        ((ObjectNode) root.path("payload")).put("queueNumber", new java.math.BigInteger("999999999999999999999999999"));
        byte[] oversized = mapper.writeValueAsBytes(root);
        assertThatThrownBy(() -> decoder.decode(oversized)).isInstanceOf(IllegalArgumentException.class);
    }

    private byte[] fixture(String state) throws Exception {
        Path root = Path.of("").toAbsolutePath();
        while (root != null && !Files.isDirectory(root.resolve("backend/clinical-service"))) root = root.getParent();
        assertThat(root).as("MediFlow monorepo root must be available for producer/consumer acceptance").isNotNull();
        return Files.readAllBytes(root.resolve("backend/clinical-service/src/test/resources/contracts/outpatient-scheduling-v2/registration."
                + state + ".v1.json"));
    }
}
